def _set_comment(table: str, column: str, comment: str | None) -> None:
    literal = "NULL" if comment is None else "'" + comment.replace("'", "''") + "'"
    op.execute(f'COMMENT ON COLUMN "{table}"."{column}" IS {literal}')


def upgrade() -> None:
    for table, name, column in INDEXES:
        op.create_index(name, table, [column], if_not_exists=True)
    for table, column, _, comment in COMMENTS:
        _set_comment(table, column, comment)


def downgrade() -> None:
    for table, column, comment, _ in COMMENTS:
        _set_comment(table, column, comment)
    for table, name, _ in INDEXES:
        op.drop_index(name, table_name=table, if_exists=True)
